Suppose $\kappa \ge 3$ is the domain size.
 Let $\mathcal{F}$ be a signature set containing the succinct unary signature $\langle 1 \rangle$ of type $\tau_1$
 and any of the following succinct ternary signatures of type $\tau_3$:
 \begin{enumerate}
  \item $\langle \kappa - 2 \pm i \kappa \sqrt{2 (\kappa - 2)}, \kappa - 2, -2 \rangle$;



  \item $\langle (\kappa - 2)^2 \pm i \kappa \sqrt{\kappa^2 - 4}, -2 (\kappa - 2), 4 \rangle$;



  \item $\langle -(2 \kappa - 3) \big[2 (\kappa - 2) \pm i \kappa \sqrt{2 (\kappa - 2)}\big], -2 (\kappa - 3) (\kappa - 2) \pm i \kappa \sqrt{2 (\kappa - 2)}, 4 (2 \kappa - 3) \rangle$
  with $\kappa \ne 4$;



  \item $\langle -\kappa^2 + 2, 2, 2 \rangle$;



  \item $\langle \kappa^2 - 6 \kappa + 6, -2 (\kappa - 3), 6 \rangle$;



  \item $\langle (\kappa - 3) (\kappa - 2)^2 \pm i \kappa (2 \kappa - 3) \sqrt{\kappa^2 - 4}, -3 (\kappa - 2)^2 \mp i \kappa \sqrt{\kappa^2 - 4}, 2 (5 \kappa - 6) \rangle$;



  \item $\langle -(\kappa - 1) \big[5 (\kappa - 2) \pm 3 i \kappa \sqrt{2 (\kappa - 2)}\big], -(\kappa - 2) (3 \kappa - 5) \pm i \kappa \sqrt{2 (\kappa - 2)}, 9 \kappa - 10 \rangle$;



  \item $\langle (\kappa - 1) \big[(\kappa - 2) (2 \kappa + 3) \pm 3 \kappa \sqrt{\kappa^2 - 5 \kappa + 6}\big], (\kappa - 3) (\kappa - 2) \mp \kappa \sqrt{\kappa^2 - 5 \kappa + 6}, -5 \kappa + 6 \rangle$;



  \item $\langle (\kappa - 1) \big[(\kappa - 2) (2 \kappa - 7) \pm 3 i \kappa \sqrt{\kappa^2 - \kappa - 2}\big], -(\kappa - 2) (5 \kappa - 7) \mp i \kappa \sqrt{\kappa^2 - \kappa - 2}, 13 \kappa - 14 \rangle$;



  \item $\langle 1,0,-2 \rangle$ with $\kappa = 3$;



  \item $\langle \pm i \sqrt{2}, 0, 1 \rangle$ with $\kappa = 3$;



  \item $\langle -1 \pm i \sqrt{2}, 0, 1 \rangle$ with $\kappa = 3$;



  \item $\langle -1 \pm 3 i \sqrt{3}, 0, 2 \rangle$ with $\kappa = 3$;



 \end{enumerate}
 Then
 \[
  \operatorname{Pl-Holant}(\mathcal{F} \cup \{\langle x,y \rangle\}) \le_T \operatorname{Pl-Holant}(\mathcal{F})
 \]
 for any $x,y \in \mathbb{C}$,
 where $\langle x,y \rangle$ is a succinct binary signature of type $\tau_2$.
